import { createContext, useContext, useState, useCallback } from "react";

const Ctx = createContext();

export const AppProvider = ({ children }) => {
  const [oturum, setOturum] = useState(null);
  const [ilanlar, setIlanlar] = useState([
    { id: 1, yuk: "Kömür", nereden: "Antalya", nereye: "İzmir", ton: 22, ucret: 8500, sure: "~7 saat", tarih: "2026-05-06", aracTip: "TIR / Kapalı Kasa", issizAd: "Mevlüt Taşıma A.Ş.", issizPuan: 4.8, aciklama: "Antalya Liman'dan İzmir OSB'ye kömür. Sabah 08:00 yükleme.", teklifSayisi: 3, durum: "aktif", belgeler: [{ ad: "İrsaliye", ok: true }, { ad: "Tartı Makbuzu", ok: true }, { ad: "Firma Ruhsatı", ok: true }] },
    { id: 2, yuk: "Çelik Boru", nereden: "Ankara", nereye: "Bursa", ton: 18, ucret: 6200, sure: "~5 saat", tarih: "2026-05-07", aracTip: "Flatbed / Lowbed", issizAd: "Kardeşler Çelik Ltd.", issizPuan: 4.6, aciklama: "Flatbed veya lowbed TIR gerekli. Vinçli yükleme.", teklifSayisi: 1, durum: "aktif", belgeler: [{ ad: "CMR Belgesi", ok: true }, { ad: "Ambalaj Listesi", ok: false }] },
    { id: 3, yuk: "Soğutmalı Gıda", nereden: "İstanbul", nereye: "Gaziantep", ton: 15, ucret: 11000, sure: "~12 saat", tarih: "2026-05-08", aracTip: "Frigorifik TIR", issizAd: "Metro Gıda Lojistik", issizPuan: 4.9, aciklama: "+4°C soğutmalı araç zorunlu. ATP belgeli kamyon tercih edilir.", teklifSayisi: 6, durum: "aktif", belgeler: [{ ad: "Soğuk Zincir Sertifikası", ok: true }, { ad: "Sıcaklık Kaydı", ok: true }, { ad: "Sağlık Belgesi", ok: true }] },
    { id: 4, yuk: "Meyve (Portakal)", nereden: "Mersin", nereye: "Ankara", ton: 20, ucret: 7800, sure: "~6 saat", tarih: "2026-05-09", aracTip: "Tenteli TIR", issizAd: "Akdeniz Tarım A.Ş.", issizPuan: 4.7, aciklama: "Portakal yükü. Havalandırmalı araç tercih edilir.", teklifSayisi: 0, durum: "aktif", belgeler: [{ ad: "Gıda Güvenlik Belgesi", ok: true }] },
    { id: 5, yuk: "İnşaat Malzemesi", nereden: "Kocaeli", nereye: "Konya", ton: 25, ucret: 9200, sure: "~4 saat", tarih: "2026-05-10", aracTip: "Damperli TIR", issizAd: "Anadolu İnşaat", issizPuan: 4.5, aciklama: "Çakıl ve kum karışık yük. Damperli araç şart.", teklifSayisi: 2, durum: "aktif", belgeler: [{ ad: "Sevk İrsaliyesi", ok: true }] },
  ]);
  const [teklifler, setTeklifler] = useState([
    { id: 1, ilanId: 1, kamyoncuAd: "Mehmet Yılmaz", plaka: "34 TYK 421", teklif: 8200, tarih: "2026-05-03", durum: "bekliyor", puan: 4.9 },
    { id: 2, ilanId: 1, kamyoncuAd: "Ali Kaya", plaka: "06 ALK 99", teklif: 8400, tarih: "2026-05-03", durum: "bekliyor", puan: 4.6 },
    { id: 3, ilanId: 3, kamyoncuAd: "Hasan Tekin", plaka: "34 HSN 07", teklif: 10500, tarih: "2026-05-02", durum: "onaylandı", puan: 4.8 },
    { id: 4, ilanId: 2, kamyoncuAd: "Yusuf Demir", plaka: "35 YDF 21", teklif: 5950, tarih: "2026-05-03", durum: "bekliyor", puan: 4.7 },
  ]);
  const [kullanicilar] = useState([
    { id: 1, ad: "Mehmet Yılmaz", rol: "kamyoncu", plaka: "34 TYK 421", puan: 4.9, durum: "aktif", kayitTarihi: "2024-01-15", sefer: 127 },
    { id: 2, ad: "Ali Kaya", rol: "kamyoncu", plaka: "06 ALK 99", puan: 4.6, durum: "aktif", kayitTarihi: "2024-03-20", sefer: 89 },
    { id: 3, ad: "Mevlüt Taşıma A.Ş.", rol: "issiz", plaka: null, puan: 4.8, durum: "aktif", kayitTarihi: "2024-02-10", sefer: 48 },
    { id: 4, ad: "Metro Gıda Lojistik", rol: "issiz", plaka: null, puan: 4.9, durum: "aktif", kayitTarihi: "2023-11-05", sefer: 93 },
  ]);

  const girisYap = useCallback((rol, ad) => {
    setOturum({ rol, ad, id: Date.now() });
  }, []);

  const cikisYap = useCallback(() => setOturum(null), []);

  const ilanEkle = useCallback((yeniIlan) => {
    setIlanlar(prev => [{ ...yeniIlan, id: Date.now(), teklifSayisi: 0, durum: "aktif" }, ...prev]);
  }, []);

  const ilanSil = useCallback((id) => {
    setIlanlar(prev => prev.filter(i => i.id !== id));
  }, []);

  const teklifGuncelle = useCallback((id, durum) => {
    setTeklifler(prev => prev.map(t => t.id === id ? { ...t, durum } : t));
  }, []);

  const teklifEkle = useCallback((yeniTeklif) => {
    setTeklifler(prev => [...prev, { ...yeniTeklif, id: Date.now(), tarih: new Date().toISOString().split("T")[0] }]);
    setIlanlar(prev => prev.map(i => i.id === yeniTeklif.ilanId ? { ...i, teklifSayisi: i.teklifSayisi + 1 } : i));
  }, []);

  return (
    <Ctx.Provider value={{ oturum, girisYap, cikisYap, ilanlar, teklifler, kullanicilar, ilanEkle, ilanSil, teklifGuncelle, teklifEkle }}>
      {children}
    </Ctx.Provider>
  );
};

export const useApp = () => useContext(Ctx);
